import { useCallback,useEffect,useMemo,useRef,useState } from 'react';
import dagre from 'dagre';
import { Plus, Save, Check, Network, ShieldCheck, Settings2, Trash2, Play, Link2, MoreHorizontal, History, BookOpen } from 'lucide-react';
import { CompositionFlow } from '../CompositionFlow.jsx';
import { ComponentSettingsDialog } from '../ComponentSettingsDialog';
import { EditorActionButton } from '../QueryEditorChrome.jsx';
import { AgentNode } from './AgentGraphNode.jsx';
import { AgentGraphLegend } from './AgentGraphLegend.jsx';
import { presentAgentEdges } from './agentGraphPresentation.js';
import { AgentVersions } from './AgentVersions.jsx';
import { JsonConfigField } from './JsonConfigField.jsx';
import { agentDesignRequest } from './agentDesignApi.js';
import { PRIMITIVE_TYPES, PRIMITIVE_PRESETS, createPrimitiveNode as createLegacyPrimitiveNode, primitiveWorkflows, resolvePrimitiveBinding, primitiveActions } from '../../../../shared/primitiveAgentModel.js';
import { JsonInspector } from './JsonInspector.jsx';
import { nativeFinishTool, nativeModelMessages } from '../../../../shared/primitiveNativeProtocol.js';
import { ProfileSettings } from './AssistantPanel';
import { applyAgentCanvasChanges,primitiveWorkflowUsage } from '../../../../shared/agentCanvasModel.js';
import { DEFAULT_NATIVE_CALL_PROTOCOL } from '../../../../shared/nativeModelAdapter.js';

const nodeTypes = { agent: AgentNode };
const createPrimitiveNode = (handler, id) => {
  const node = createLegacyPrimitiveNode(handler, id); node.operationVersion = 2;
  if (handler === 'llm') Object.assign(node.settings, { purpose: '', responseSchema: null, maxModelCalls: 20, maxRepeatedCalls: 3, protocolInstructions: DEFAULT_NATIVE_CALL_PROTOCOL, maxOutputTokens: 8192, skillIds: [] });
  if (handler === 'tool') node.settings.mode = 'dispatch';
  return node;
};
const id = prefix => `${prefix}-${crypto.randomUUID()}`;
function BindingField({ label, binding, onChange, testId }) {
  binding = binding && typeof binding === 'object' && !Array.isArray(binding) ? binding : {};
  const mode = Object.hasOwn(binding ?? {}, 'path') ? 'path' : Object.hasOwn(binding ?? {}, 'value') ? 'value' : Object.hasOwn(binding, 'merge') ? 'merge' : 'fields';
  return <fieldset className="creatio-settings-category"><legend>{label}</legend><label>Source<select data-testid={`${testId}-source`} value={mode} onChange={event => onChange(event.target.value === 'path' ? { path: 'payload' } : event.target.value === 'value' ? { value: null } : event.target.value === 'merge' ? { merge: [{ path: 'payload' }] } : { fields: {} })}><option value="path">State path</option><option value="value">Constant JSON</option><option value="fields">Construct object</option><option value="merge">Merge object bindings</option></select></label>
    {mode === 'path' ? <label>JSON path<input data-testid={testId} value={binding.path} onChange={event => onChange({ path: event.target.value })} /><small>entry: workflow entry; payload: preceding output; variables: explicitly saved values.</small></label>
      : mode === 'value' ? <JsonConfigField label="Constant" testId={testId} value={binding.value} onChange={value => onChange({ value })} />
        : mode === 'merge' ? <JsonConfigField label="Ordered object bindings" testId={testId} value={binding.merge} onChange={merge => onChange({ merge })} />
        : <><p>Each named field selects its own source. Unlisted fields are not inherited.</p>{Object.entries(binding.fields ?? {}).map(([name, source]) => <div key={name}><strong>{name}</strong><BindingField label={name} testId={`${testId}-${name}`} binding={source} onChange={next => onChange({ fields: { ...binding.fields, [name]: next } })} /><button onClick={() => onChange({ fields: Object.fromEntries(Object.entries(binding.fields).filter(([key]) => key !== name)) })}>Remove field</button></div>)}<button onClick={() => { let name = 'field'; for (let index = 2; Object.hasOwn(binding.fields ?? {}, name); index++) name = `field${index}`; onChange({ fields: { ...binding.fields, [name]: { path: 'payload' } } }); }}>Add field</button><JsonConfigField label="Field names and bindings" testId={testId} value={binding.fields ?? {}} onChange={fields => onChange({ fields })} /></>}
  </fieldset>;
}

export function PrimitiveAgentDesigner({ workspaceId, draft, catalog, profiles, live, onDraft, onCatalog, onSelect, onClose }) {
  const [workflowId, setWorkflowId] = useState('assistant');
  const [dirty, setDirty] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [diagnostics, setDiagnostics] = useState([]);
  const [validated, setValidated] = useState(false);
  const [edit, setEdit] = useState(null);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [versions, setVersions] = useState(false);
  const [flow, setFlow] = useState(null);
  const optionsRef = useRef(null);
  useEffect(() => {
    const closeOptions = event => { if (!optionsRef.current?.contains(event.target) && optionsRef.current) optionsRef.current.open = false; };
    document.addEventListener('pointerdown', closeOptions);
    return () => document.removeEventListener('pointerdown', closeOptions);
  }, []);
  const [preview, setPreview] = useState(null);
  const [sample, setSample] = useState({ entry: { request: 'Explain the current query', workspace: {} }, payload: {}, variables: {} });
  const root = draft.definition, workflow = primitiveWorkflows(root).find(([key]) => key === workflowId)?.[1] ?? root;
  const changeRoot = next => { onDraft({ ...draft, definition: next }); setDirty(true); setValidated(false); setError(''); };
  const change = next => changeRoot(workflowId === 'assistant' ? next : { ...root, [workflowId]: next });
  const run = async work => { setBusy(true); setError(''); try { await work(); } catch (error) { setError(error.message); } finally { setBusy(false); } };
  const save = () => run(async () => { const saved = await agentDesignRequest(`/workflow-drafts/${draft.id}`, { method: 'PUT', body: { workspaceId, expectedDraftVersion: draft.draftVersion ?? 0, definition: root } }); onDraft(saved); onCatalog({ ...catalog, workflows: catalog.workflows.map(item => item.id === draft.id ? saved : item) }); setDirty(false); });
  const openNode = useCallback(node => { setPreview(null); setEdit({ kind: 'node', value: structuredClone(node) }); },[]);
  const nodes = useMemo(()=>workflow.nodes.map(node => ({ ...node, type: 'agent', dragHandle: '.ai-agent-node-drag-handle', data: { ...node, diagnostics: diagnostics.filter(item => item.nodeId === node.id && item.workflow === workflowId).map(item => item.message), edit: () => openNode(node), workflowTarget: node.handler === 'workflow' ? node.settings.workflowRef : null, workflowName: root[node.settings.workflowRef]?.name, openWorkflow: setWorkflowId,
    running: live?.workflowId === workflowId && live.nodeId === node.id,
    modelName: node.handler === 'llm' ? profiles.find(profile => profile.id === (node.settings.profileId ?? workflow.profileId ?? root.profileId))?.model : null,
  } })),[workflow,root,diagnostics,workflowId,openNode,profiles,live]);
  const edges = useMemo(()=>presentAgentEdges(workflow),[workflow]);
  const usage=useMemo(()=>primitiveWorkflowUsage(root,workflowId),[root,workflowId]);
  const settings = edit?.kind === 'node' ? edit.value.settings : null;
  const nodeSkills = edit?.nodeSkills ?? root.resources?.skills ?? [];
  const updateSettings = patch => setEdit(current => ({ ...current, value: { ...current.value, settings: { ...current.value.settings, ...patch } } }));
  const updateNode = patch => setEdit(current => ({ ...current, value: { ...current.value, ...patch } }));
  const applyEdit = () => {
    if (document.querySelector('[role="dialog"] [data-config-invalid], dialog [data-config-invalid]')) { setError('Correct invalid JSON before saving.'); return; }
    if (edit.kind === 'node') {
      if (edit.nodeSkills?.some(skill => (skill.version !== root.resources?.skills?.find(prior => prior.id === skill.id)?.version) && (!skill.title?.trim() || !skill.description?.trim() || !skill.body?.trim()))) { setError('Each edited skill needs a name, description and instructions.'); return; }
      const next = { ...workflow, nodes: workflow.nodes.some(node => node.id === edit.value.id) ? workflow.nodes.map(node => node.id === edit.value.id ? edit.value : node) : [...workflow.nodes, edit.value] };
      const updated = workflowId === 'assistant' ? next : { ...root, [workflowId]: next };
      changeRoot(edit.nodeSkills ? { ...updated, resources: { ...root.resources, skills: edit.nodeSkills } } : updated);
    }
    else if (edit.kind === 'edge') change({ ...workflow, edges: workflow.edges.some(edge => edge.id === edit.value.id) ? workflow.edges.map(edge => edge.id === edit.value.id ? edit.value : edge) : [...workflow.edges, edit.value] });
    else if (edit.kind === 'resources') changeRoot({ ...root, resources: edit.value });
    else if (edit.kind === 'settings') changeRoot({ ...root, ...edit.value });
    setEdit(null); setPreview(null);
  };
  return <section className="ai-design-page" data-testid="ai-primitive-designer">
    <header className="workspace-toolbar"><h2>Consilium / Agent builder</h2><button onClick={onClose}>Close</button></header>
    <div className="ai-design-controls ai-agent-commandbar" role="region" aria-label="Agent editing commands" data-testid="ai-agent-commandbar">
      <div className="ai-agent-command-group ai-agent-identity" role="group" aria-label="Agent management">
      <label>Agent<select data-testid="ai-agent-selector" disabled={busy || dirty} value={draft.id} onChange={event => onSelect(catalog.workflows.find(item => item.id === event.target.value))}>{catalog.workflows.map(item => <option key={item.id} value={item.id}>{item.definition.name} / v{item.version}</option>)}</select></label>
      <EditorActionButton icon={Plus} data-testid="ai-agent-new" disabled={busy || dirty} onClick={() => setEdit({ kind: 'new', value: { name: 'New agent', mode: 'primitive-blank' } })}>New agent</EditorActionButton>
      <details ref={optionsRef} className="ai-agent-options" onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) event.currentTarget.open = false; }} onKeyDown={event => { if (event.key === 'Escape') { event.currentTarget.open = false; event.currentTarget.querySelector('summary')?.focus(); } }}>
        <summary aria-label="Agent options" title="Agent settings and versions" data-testid="ai-agent-options"><MoreHorizontal size={17} aria-hidden="true" /></summary>
        <div className="ai-agent-options-panel" onClick={event => { if (event.target.closest('button:not(:disabled)')) event.currentTarget.closest('details').open = false; }}>
      <span className="ai-agent-options-heading">Manage agent</span>
      <EditorActionButton icon={Settings2} onClick={() => setEdit({ kind: 'settings', value: { name: root.name, profileId: root.profileId ?? null } })}>Settings</EditorActionButton>
      <EditorActionButton icon={History} data-testid="ai-agent-versions" disabled={busy || dirty} onClick={() => setVersions(true)}>Versions{catalog.activeId === draft.id ? ` / active v${catalog.activeVersion}` : ''}</EditorActionButton>
      {draft.id === 'langvision-coding-agent' && !root.nodes.some(node => node.id === 'approach') && <EditorActionButton icon={Network} disabled={busy || dirty} onClick={() => run(async () => {
        const upgraded = await agentDesignRequest(`/workflows/${draft.id}/coding-planning-draft`, { method: 'POST', body: { workspaceId, expectedVersion: draft.version, expectedDraftVersion: draft.draftVersion ?? 0 } });
        onDraft(upgraded); onCatalog({ ...catalog, workflows: catalog.workflows.map(item => item.id === draft.id ? upgraded : item) }); setValidated(false);
      })}>Add approach planning to draft</EditorActionButton>}
      {root.nodes.some(node => node.handler === 'llm' && node.operationVersion === 1) && <EditorActionButton icon={Network} disabled={busy || dirty} onClick={() => run(async () => { const migrated = await agentDesignRequest(`/workflows/${draft.id}/native-draft`, { method: 'POST', body: { workspaceId, expectedDraftVersion: draft.draftVersion ?? 0 } }); onDraft(migrated); setValidated(false); setPreview(migrated.migrationReport); })}>Migrate native protocol</EditorActionButton>}
      <EditorActionButton icon={Trash2} data-testid="ai-agent-delete" title={catalog.workflows.find(item => item.id === draft.id)?.deletionReason ?? (catalog.activeId === draft.id ? 'Activate another agent before deleting.' : 'Delete this agent; historical evidence is retained.')} disabled={busy || dirty || catalog.activeId === draft.id || catalog.workflows.find(item => item.id === draft.id)?.systemPinned} onClick={() => setDeleteOpen(true)}>Delete agent</EditorActionButton>
        </div>
      </details>
      </div>
      <div className="ai-agent-command-group ai-agent-compose" role="group" aria-label="Graph composition">
      <EditorActionButton icon={Plus} data-testid="ai-agent-add-node" disabled={busy} onClick={() => setEdit({ kind: 'node', isNew: true, value: createPrimitiveNode('llm', id('node')) })}>Add node</EditorActionButton>
      <EditorActionButton icon={Link2} data-testid="ai-primitive-add-action" disabled={busy || workflow.nodes.length < 2} onClick={() => setEdit({ kind: 'edge', isNew: true, value: { id: id('action'), source: workflow.nodes[0].id, target: workflow.nodes[1].id, name: 'Continue', description: '', kind: 'success' } })}>Add action</EditorActionButton>
      <EditorActionButton icon={BookOpen} data-testid="ai-primitive-skills" onClick={() => setEdit({ kind: 'resources', value: structuredClone(root.resources ?? { skills: [] }) })}>Skills</EditorActionButton>
      <EditorActionButton icon={Network} data-testid="ai-agent-auto-layout" onClick={() => { const graph = new dagre.graphlib.Graph().setGraph({ rankdir: 'LR', ranksep: 110, nodesep: 80 }).setDefaultEdgeLabel(() => ({})); for (const node of workflow.nodes) graph.setNode(node.id, { width: 260, height: 170 }); for (const edge of workflow.edges) graph.setEdge(edge.source, edge.target); dagre.layout(graph); change({ ...workflow, nodes: workflow.nodes.map(node => ({ ...node, position: { x: graph.node(node.id).x, y: graph.node(node.id).y } })) }); requestAnimationFrame(() => flow?.fitView()); }}>Auto layout</EditorActionButton>
      </div>
      <div className="ai-agent-command-group ai-agent-publish" role="group" aria-label="Draft publishing">
      <span className="ai-agent-draft-status" role="status" data-testid="ai-agent-draft-status"><Save size={14} aria-hidden="true" />{dirty ? 'Unsaved changes' : 'Saved'}</span>
      <EditorActionButton icon={Save} data-testid="ai-agent-save" disabled={!dirty || busy} onClick={save}>Save draft</EditorActionButton>
      <EditorActionButton icon={ShieldCheck} data-testid="ai-agent-validate" disabled={busy} onClick={() => run(async () => { const result = await agentDesignRequest(`/workflows/${draft.id}/validate`, { method: 'POST', body: { workspaceId, definition: root } }); setDiagnostics(result.diagnostics); setValidated(result.valid); })}>{validated ? 'Validated' : 'Validate'}</EditorActionButton>
      <EditorActionButton icon={Check} data-testid="ai-agent-activate" disabled={!validated || dirty || busy || !draft.draftVersion} onClick={() => run(async () => { const result = await agentDesignRequest(`/workflows/${draft.id}/activate`, { method: 'POST', body: { workspaceId, expectedDraftVersion: draft.draftVersion } }); onDraft({ ...draft, version: result.version }); onCatalog({ ...catalog, activeId: result.id, activeVersion: result.version }); })}>Activate</EditorActionButton>
      </div>
    </div>
    <div className="ai-workflow-tabs">{primitiveWorkflows(root).map(([key, graph]) => <button key={key} title={primitiveWorkflowUsage(root,key).entry} data-testid={`ai-workflow-${key}`} data-unused={primitiveWorkflowUsage(root,key).unused} className={workflowId === key ? 'active' : ''} onClick={() => setWorkflowId(key)}>{graph.name}{primitiveWorkflowUsage(root,key).unused?' / unused':''}</button>)}<label>Step budget<input aria-label="Step budget" type="number" min={1} max={1000} value={workflow.maxSteps} onChange={event => change({ ...workflow, maxSteps: Number(event.target.value) })} /></label></div>
    <details className="ai-workflow-purpose" data-testid="ai-primitive-workflow-purpose"><summary>{usage.entry} / {usage.modelNodes} model node(s) / {usage.tools.length} tools</summary><p>One agent, multiple optional workflows. Matching graph shapes do not mean matching instructions, permissions or result contracts. The conversation can investigate, author, validate and answer directly; child workflows run only through a saved invocation or their separate API entry point.</p><p>Result fields: {usage.resultFields.join(', ')||'Configured by End bindings'}.</p>{usage.callers.map(caller=><button key={`${caller.workflowId}:${caller.nodeId}`} className="ghost-button" onClick={()=>setWorkflowId(caller.workflowId)}>Called by {caller.label}</button>)}{usage.unused&&<p>This workflow is retained for compatibility and editing. It is not a mandatory answer/review stage and incurs no model calls unless you connect an invocation.</p>}<p title={usage.tools.join(', ')}>Allowed tools: {usage.tools.join(', ')||'None'}.</p></details>
    <AgentGraphLegend />
    <div className="universum-flow ai-agent-flow" data-testid="ai-agent-flow"><CompositionFlow key={`${draft.id}:${workflowId}`} onInit={setFlow} nodes={nodes} edges={edges} nodeTypes={nodeTypes} fitView minZoom={.15} maxZoom={1.8} autoPanOnNodeFocus={false} zoomOnDoubleClick={false}
      onNodesChange={changes => {if(busy)return; const next=applyAgentCanvasChanges(workflow.nodes,changes);if(next===workflow.nodes)return;const ids=new Set(next.map(node=>node.id));change({...workflow,nodes:next,edges:workflow.edges.filter(edge=>ids.has(edge.source)&&ids.has(edge.target))});}}
      onConnect={connection => setEdit({ kind: 'edge', isNew: true, value: { id: id('action'), source: connection.source, target: connection.target, name: 'Continue', description: '', kind: 'success' } })}
      onEdgesChange={changes => { const removed = changes.filter(change => change.type === 'remove').map(change => change.id); if (removed.length) change({ ...workflow, edges: workflow.edges.filter(edge => !removed.includes(edge.id)) }); }}
      onEdgeDoubleClick={(_, edge) => setEdit({ kind: 'edge', value: structuredClone(workflow.edges.find(item => item.id === edge.id)) })} /></div>
    <p className="ai-design-help">One LLM node makes one call. Connect explicit back-edges for retries. Drag headers to arrange; use Edit to configure. Only bound JSON enters model context.</p>
    {diagnostics.length > 0 && <ul role="alert">{diagnostics.map((item, index) => <li key={index}>{item.message}</li>)}</ul>}{error && <p role="alert">{error}</p>}
    {deleteOpen && <ComponentSettingsDialog surfaceLabel="Consilium" title="Delete agent" onClose={() => setDeleteOpen(false)}>
      <p>Delete {root.name}? It will no longer be selectable or executable. Immutable revisions and historical executions are retained.</p><button onClick={() => setDeleteOpen(false)}>Cancel</button><button data-testid="ai-agent-delete-confirm" disabled={busy} onClick={() => run(async () => {
        await agentDesignRequest(`/workflows/${encodeURIComponent(draft.id)}`, { method: 'DELETE', body: { workspaceId, expectedVersion: draft.version, expectedDraftVersion: draft.draftVersion ?? 0 } });
        const refreshed = await agentDesignRequest(`/workflows?workspaceId=${encodeURIComponent(workspaceId)}`);
        onCatalog(refreshed); onSelect(refreshed.workflows.find(item => item.id === refreshed.activeId)); setDeleteOpen(false);
      })}>Delete agent</button>{error && <p role="alert">{error}</p>}
    </ComponentSettingsDialog>}
    {versions && <AgentVersions workspaceId={workspaceId} agentId={draft.id} draftVersion={draft.draftVersion ?? 0} onClose={() => setVersions(false)} onClone={result => { onDraft({ ...result, version: draft.version }); setDirty(false); setValidated(false); }} onActivate={result => onCatalog({ ...catalog, activeId: result.id, activeVersion: result.version })} />}
    {edit && <ComponentSettingsDialog className={`lv-agent-settings-dialog${edit.kind === 'node' ? ' lv-node-dialog' : ''}`} surfaceLabel="Agent Editor" title={edit.kind === 'node' ? edit.isNew ? 'Add node' : `Edit ${edit.value.label}` : edit.kind === 'edge' ? 'Action / transition' : edit.kind === 'resources' ? 'Versioned skills' : 'Agent settings'} onClose={() => { setEdit(null); setPreview(null); }}
      footer={<footer className="ai-design-dialog-actions">{!edit.isNew && ['node', 'edge'].includes(edit.kind) && <EditorActionButton icon={Trash2} onClick={() => { const node = edit.kind === 'node'; change({ ...workflow, nodes: node ? workflow.nodes.filter(item => item.id !== edit.value.id) : workflow.nodes, edges: workflow.edges.filter(edge => node ? edge.source !== edit.value.id && edge.target !== edit.value.id : edge.id !== edit.value.id) }); setEdit(null); }}>Delete</EditorActionButton>}<button data-testid="ai-primitive-cancel" onClick={() => { setEdit(null); setPreview(null); }}>Cancel</button><button data-testid="ai-primitive-save-node" disabled={busy} onClick={edit.kind === 'new' ? () => run(async () => { const created = await agentDesignRequest('/workflows', { method: 'POST', body: { workspaceId, ...edit.value, profileId: root.profileId } }); onCatalog({ ...catalog, workflows: [...catalog.workflows, created] }); onSelect(created); setEdit(null); }) : applyEdit}>{edit.kind === 'new' ? 'Create agent' : 'Save'}</button></footer>}>
      {edit.kind === 'new' && <><label>Name<input data-testid="ai-agent-name" value={edit.value.name} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, name: event.target.value } }))} /></label><label>Start from<select data-testid="ai-agent-creation-mode" value={edit.value.mode} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, mode: event.target.value } }))}><option value="primitive-blank">Blank primitive agent</option><option value="primitive-starter">Primitive starter</option></select></label><p>Creates a separate draft. The active agent is unchanged.</p></>}
      {edit.kind === 'node' && <>
        <nav className="lv-node-sections" aria-label="Node settings sections">
          <button type="button" onClick={event => event.currentTarget.closest('dialog').querySelector('#node-basics')?.scrollIntoView({ block: 'start' })}>Basics</button>
          {edit.value.handler === 'llm' && <>
            <button type="button" onClick={event => event.currentTarget.closest('dialog').querySelector('#node-model')?.scrollIntoView({ block: 'start' })}>Model</button>
            <button type="button" onClick={event => event.currentTarget.closest('dialog').querySelector('#node-instructions')?.scrollIntoView({ block: 'start' })}>Instructions</button>
            <button type="button" onClick={event => event.currentTarget.closest('dialog').querySelector('#node-skills')?.scrollIntoView({ block: 'start' })}>Skills</button>
          </>}
          {['llm', 'tool'].includes(edit.value.handler) && <button type="button" onClick={event => { const tools = event.currentTarget.closest('dialog').querySelector('#node-tools'); tools.open = true; tools.scrollIntoView({ block: 'start' }); }}>Tools</button>}
          <button type="button" onClick={event => event.currentTarget.closest('dialog').querySelector('#node-results')?.scrollIntoView({ block: 'start' })}>Results and routing</button>
        </nav>
        {edit.value.handler === 'llm' && <fieldset id="node-model" className="creatio-settings-category lv-node-model"><legend>Model and reasoning</legend>
          <label>Model profile<select data-testid="ai-primitive-profile" value={settings.profileId ?? ''} onChange={event => updateSettings({ profileId: event.target.value || null })}><option value="">Inherit workflow or agent default</option>{profiles.map(profile => <option key={profile.id} value={profile.id}>{profile.displayName} · {profile.model} · {profile.provider === 'openai-compatible' ? profile.reasoningEffort || 'provider default' : profile.thinkingMode ?? 'off'}</option>)}</select></label>
          <small>Only this node uses the selected profile. Nodes that do not invoke a model do not need one.</small>
          <details><summary>Manage model profiles</summary><ProfileSettings workspaceId={workspaceId} initiallyOpen/></details>
        </fieldset>}
        {edit.value.handler === 'llm' && <fieldset id="node-skills" className="creatio-settings-category"><legend>Skills</legend>
          <p>Enable skill discovery tools on this node and its connected Tool node. The model loads discoverable skills on demand. Only skills marked as instructions are included in every model request.</p>
          {edit.value.operationVersion === 2 && <label>Skill scope<select value={settings.skillIds === undefined ? 'all' : 'selected'} onChange={event => updateSettings({ skillIds: event.target.value === 'all' ? undefined : [...(settings.instructionSkillIds ?? [])] })}><option value="all">All agent skills</option><option value="selected">Only selected skills</option></select></label>}
          {nodeSkills.map(skill => {
            const others = primitiveWorkflows(root).flatMap(([key, graph]) => graph.nodes.filter(node => node.handler === 'llm' && node.operationVersion === 2 && (key !== workflowId || node.id !== edit.value.id) && (node.settings.instructionSkillIds?.includes(skill.id) || node.settings.skillIds?.includes(skill.id))).map(node => `${graph.name} / ${node.label}`));
            const inherited = primitiveWorkflows(root).some(([key, graph]) => graph.nodes.some(node => node.handler === 'llm' && node.operationVersion === 2 && (key !== workflowId || node.id !== edit.value.id) && node.settings.skillIds === undefined));
            const allowed = !settings.skillIds || settings.skillIds.includes(skill.id);
            const editSkill = patch => setEdit(current => ({ ...current, nodeSkills: nodeSkills.map(item => item.id === skill.id ? { ...item, ...patch, version: (root.resources?.skills?.find(prior => prior.id === item.id)?.version ?? 0) + 1 } : item) }));
            return <details key={skill.id} className="creatio-settings-category"><summary>{skill.title || 'New skill'} · v{skill.version}</summary>
              {others.length > 0 && <p>Also available to: {others.join(', ')}. Saving edits affects those nodes in the next activated revision.</p>}
              {inherited && <p>Nodes set to “All agent skills” also see changes to this resource.</p>}
              {settings.skillIds !== undefined && <label><input type="checkbox" checked={allowed} onChange={event => updateSettings({ skillIds: event.target.checked ? [...settings.skillIds, skill.id] : settings.skillIds.filter(id => id !== skill.id), instructionSkillIds: event.target.checked ? settings.instructionSkillIds : settings.instructionSkillIds?.filter(id => id !== skill.id) })} /> Allow {skill.title}</label>}
              {edit.value.operationVersion === 2 && allowed && <label><input type="checkbox" checked={settings.instructionSkillIds?.includes(skill.id) ?? false} onChange={event => updateSettings({ instructionSkillIds: event.target.checked ? [...(settings.instructionSkillIds ?? []), skill.id] : settings.instructionSkillIds.filter(id => id !== skill.id) })} /> Include as instructions</label>}
              <label>Name<input value={skill.title} onChange={event => editSkill({ title: event.target.value })} /></label>
              <label>Discovery description<input value={skill.description} onChange={event => editSkill({ description: event.target.value })} /></label>
              <label>Instructions<textarea rows={6} value={skill.body} onChange={event => editSkill({ body: event.target.value })} /></label>
              <button type="button" disabled={others.length > 0} onClick={() => setEdit(current => ({ ...current, nodeSkills: nodeSkills.filter(item => item.id !== skill.id), value: { ...current.value, settings: { ...settings, skillIds: settings.skillIds?.filter(id => id !== skill.id), instructionSkillIds: settings.instructionSkillIds?.filter(id => id !== skill.id) } } }))}>Delete skill</button>
              {others.length > 0 && <small>Detach this skill from the other nodes before deleting it.</small>}
            </details>;
          })}
          <button type="button" onClick={() => {
            const skillId = id('skill');
            setEdit(current => ({ ...current, nodeSkills: [...nodeSkills, { id: skillId, title: 'New skill', description: '', body: '', version: 1 }],
              value: { ...current.value, settings: { ...settings, skillIds: settings.skillIds ? [...settings.skillIds, skillId] : undefined } } }));
          }}>Create skill</button>
        </fieldset>}
        <fieldset id="node-basics" className="creatio-settings-category"><legend>Identity</legend><label>Operation<select data-testid="ai-primitive-operation" value={edit.value.handler} onChange={event => {
          if (edit.isNew) setEdit(current => ({ ...current, value: { ...createPrimitiveNode(event.target.value, current.value.id), position: current.value.position } }));
          else setEdit(current => ({ ...current, replacement: event.target.value }));
        }}>{PRIMITIVE_TYPES.map(type => <option key={type.id} value={type.id}>{type.title} · {type.id}</option>)}</select></label>
          {edit.replacement && <p>Replacing the operation resets its incompatible settings, but keeps the node identity and links. <button onClick={() => setEdit(current => ({ ...current, replacement: null, value: { ...createPrimitiveNode(current.replacement, current.value.id), label: current.value.label, description: current.value.description, position: current.value.position } }))}>Replace operation</button><button onClick={() => setEdit(current => ({ ...current, replacement: null }))}>Keep current operation</button></p>}
          {edit.isNew && <label>Stable node ID<input data-testid="ai-primitive-node-id" value={edit.value.id} onChange={event => updateNode({ id: event.target.value })} /></label>}<label>Label<input data-testid="ai-node-label" value={edit.value.label} onChange={event => updateNode({ label: event.target.value })} /></label><label>Description<textarea data-testid="ai-node-description" value={edit.value.description ?? ''} onChange={event => updateNode({ description: event.target.value })} /></label><small>Label and description affect presentation, not execution.</small></fieldset>
        <BindingField label="Input JSON" testId="ai-primitive-input" binding={settings.input} onChange={input => updateSettings({ input })} />
        {['llm', 'tool', 'human'].includes(edit.value.handler) && <fieldset className="creatio-settings-category"><legend>Execution protocol</legend><label>Operation version<select data-testid="ai-primitive-protocol" value={edit.value.operationVersion} onChange={event => {
          const version = Number(event.target.value);
          updateNode({ operationVersion: version, settings: { ...settings, ...(version === 2 && edit.value.handler === 'llm' ? { maxModelCalls: settings.maxModelCalls ?? 20, maxRepeatedCalls: settings.maxRepeatedCalls ?? 3 } : {}), ...(edit.value.handler === 'tool' ? { mode: version === 2 ? 'dispatch' : 'prepare' } : {}) } });
        }}><option value={1}>Version 1 · pinned JSON protocol</option><option value={2}>Version 2 · native calls and saved exits</option></select></label><small>Version 2 sends native tool definitions and finish_step. Every request follows a visible graph edge; no hidden tool loop.</small></fieldset>}
        {edit.value.handler === 'llm' && edit.value.operationVersion === 2 && <>
          <fieldset className="creatio-settings-category"><legend>Purpose</legend><label>Execution purpose<textarea data-testid="ai-primitive-purpose" value={settings.purpose ?? ''} onChange={event => updateSettings({ purpose: event.target.value })} /></label><small>Purpose and system instructions are sent to the model. The node label and description are presentation only.</small></fieldset>
          <fieldset className="creatio-settings-category"><legend>Input and context</legend><JsonConfigField label="Optional input contract · types, descriptions and examples" value={settings.inputSchema ?? null} onChange={inputSchema => updateSettings({ inputSchema: inputSchema || undefined })} /><label><input type="checkbox" checked={Boolean(settings.context)} onChange={event => updateSettings({ context: event.target.checked ? { path: 'entry' } : undefined })} />Include explicitly selected shared context</label>{settings.context && <BindingField label="Shared context" testId="ai-primitive-context" binding={settings.context} onChange={context => updateSettings({ context })} />}<p>Input defaults to the preceding node output. Recorded observations and native call/result messages remain separate from generated JSON. Only selected context is sent; captured debug data is not inherited.</p></fieldset>
          <fieldset className="creatio-settings-category"><legend>Recovery</legend>{[['maxModelCalls', 'Total model-call cap', 500], ['maxNoProgressCalls', 'Calls without new evidence', 500], ['maxRepeatedCalls', 'Repeated identical request limit', 100]].map(([field, label, max]) => <label key={field}>{label}<input type="number" min={1} max={max} value={settings[field] ?? ''} onChange={event => updateSettings({ [field]: Number(event.target.value) })} /></label>)}<p>New successful tool evidence renews the no-progress allowance. Repeated results and progress prose do not. The total-call and graph-step caps never reset.</p></fieldset>
        </>}
        {edit.value.handler === 'llm' && <fieldset id="node-instructions" className="creatio-settings-category"><legend>Instructions</legend>
          {edit.value.operationVersion === 1 && <label>Preset<select defaultValue="" onChange={event => event.target.value && updateSettings(structuredClone(PRIMITIVE_PRESETS[event.target.value]))}><option value="">Choose initial instructions</option>{Object.keys(PRIMITIVE_PRESETS).map(key => <option key={key}>{key}</option>)}</select></label>}
          <label>System prompt<textarea data-testid="ai-primitive-system-prompt" rows={12} value={settings.systemPrompt} onChange={event => updateSettings({ systemPrompt: event.target.value })} /></label>
          {edit.value.operationVersion === 2 && <fieldset className="creatio-settings-category"><legend>Native model protocol</legend><p>Qwen and GPT-OSS use Ollama native calls. Ollama handles model templates; text is never converted into executable actions. These saved instructions are sent after the system prompt and appear in Historia.</p><label>Native call instructions<textarea data-testid="ai-native-call-instructions" rows={6} value={settings.protocolInstructions ?? ''} onChange={event => updateSettings({ protocolInstructions: event.target.value })}/></label><button onClick={() => updateSettings({ protocolInstructions: DEFAULT_NATIVE_CALL_PROTOCOL })}>Use native call guidance</button><label>Output token limit<input data-testid="ai-native-output-tokens" type="number" min={1} max={131072} value={settings.maxOutputTokens ?? 8192} onChange={event => updateSettings({ maxOutputTokens: Number(event.target.value) })}/></label></fieldset>}
          <small>Use the system prompt for the node’s task and skills for reusable guidance.</small>
          <JsonConfigField label="Tools allowed before a task plan" value={settings.planExemptTools??[]} onChange={planExemptTools=>updateSettings({planExemptTools})}/>
          <label><input type="checkbox" checked={settings.requirePlan===true} onChange={event=>updateSettings({requirePlan:event.target.checked})}/> Require a reported outcome plan before product actions and completion</label>
          <JsonConfigField label={edit.value.operationVersion === 2 ? 'Optional default result schema · null means exit-specific only' : 'Response JSON schema'} testId="ai-primitive-schema" value={settings.responseSchema} onChange={responseSchema => updateSettings({ responseSchema })} />
          <p>{edit.value.operationVersion === 2 ? 'Order: purpose and instructions, bound input and selected context, then native assistant/tool messages. Native tools execute on connected Tool nodes. finish_step selects a saved exit and validates its result; intermediate requests need no final-result JSON.' : 'The model receives the system prompt followed by bound JSON. Named actions are supplied only when Action field is configured. Tool schemas do not execute tools.'}</p>
        </fieldset>}
        {['llm', 'tool'].includes(edit.value.handler) && <details id="node-tools" className="creatio-settings-category"><summary>Available tools · {settings.toolNames?.length ?? 0} selected</summary><div className="ai-primitive-tool-scope">{catalog.tools.map(tool => <label key={tool.name}><input type="checkbox" checked={settings.toolNames?.includes(tool.name) ?? false} onChange={event => updateSettings({ toolNames: event.target.checked ? [...(settings.toolNames ?? []), tool.name] : settings.toolNames.filter(name => name !== tool.name) })} />{tool.name} · {tool.risk}</label>)}</div></details>}
        {edit.value.handler === 'tool' && <fieldset className="creatio-settings-category"><legend>Execution</legend><label>Mode<select value={settings.mode} onChange={event => updateSettings({ mode: event.target.value })}>{edit.value.operationVersion === 2 && <option value="dispatch">Dispatch native requests · prepare, approve, execute</option>}<option value="prepare">Prepare / validate</option><option value="execute">Execute prepared requests</option></select></label><label>Request collection path<input value={settings.requestsPath} onChange={event => updateSettings({ requestsPath: event.target.value })} /></label><JsonConfigField label="Additional approval risks" value={settings.approvalRisks ?? []} onChange={approvalRisks => updateSettings({ approvalRisks })} /><small>Mutations always require proof of exact human approval. Tool implementation and authorization remain runtime contracts.</small></fieldset>}
        {edit.value.handler === 'data' && <fieldset className="creatio-settings-category"><legend>Declarative operations</legend><p>Ordered map, merge, append, select, update, counter and assert operations. No executable JavaScript.</p><JsonConfigField label="Operations" testId="ai-primitive-data" value={settings.operations} onChange={operations => updateSettings({ operations })} /></fieldset>}
        {edit.value.handler === 'workflow' && <label>Called workflow<select data-testid="ai-primitive-workflow-ref" value={settings.workflowRef} onChange={event => updateSettings({ workflowRef: event.target.value })}><option value="">Select workflow</option>{primitiveWorkflows(root).filter(([key]) => key !== workflowId && key !== 'assistant').map(([key, graph]) => <option key={key} value={key}>{graph.name}</option>)}</select><small>Receives only Input JSON and returns only its End JSON. The parent agent revision pins the child definition.</small></label>}
        {edit.value.handler === 'human' && <fieldset className="creatio-settings-category"><legend>User interaction</legend><label>Kind<select value={settings.kind} onChange={event => updateSettings({ kind: event.target.value })}><option value="approval">Approval</option><option value="clarification">Clarification</option></select></label>{(settings.kind === 'approval' ? ['requestsPath', 'prompt'] : ['promptPath', 'optionsPath', 'recommendationPath', 'reasonPath']).map(field => <label key={field}>{field}<input value={settings[field] ?? ''} onChange={event => updateSettings({ [field]: event.target.value })} /></label>)}
          {settings.kind==='approval'&&<><label>Approval wording<select data-testid="ai-approval-question-mode" value={settings.questionMode??'template'} onChange={event=>updateSettings({questionMode:event.target.value})}><option value="template">Saved prompt</option><option value="model">One traced model call inside this Human node</option></select></label><label>Approval question instructions<textarea data-testid="ai-approval-instructions" rows={5} value={settings.questionInstructions??''} onChange={event=>updateSettings({questionInstructions:event.target.value})}/></label><p>The model explains exact actions, rationale, prior outcomes and expected results. It cannot change the approval scope or approve actions. The request and response are recorded in Historia. If wording fails, the saved prompt is used with authoritative action details.</p></>}
        </fieldset>}
        {edit.value.handler==='human'&&settings.kind==='approval'&&settings.questionMode==='model'&&<label>Approval wording model<select data-testid="ai-approval-profile" value={settings.profileId??''} onChange={event=>updateSettings({profileId:event.target.value||null})}><option value="">Workflow / agent profile</option>{profiles.map(profile=><option key={profile.id} value={profile.id}>{profile.displayName} / {profile.model}</option>)}</select></label>}
        {edit.value.handler === 'end' && <fieldset className="creatio-settings-category"><legend>Completion</legend><label>Mode<select value={settings.mode} onChange={event => updateSettings({ mode: event.target.value })}><option value="return">Return JSON to caller</option><option value="publish">Publish final answer</option></select></label>{settings.mode === 'publish' && <label>Response field<input value={settings.responsePath} onChange={event => updateSettings({ responsePath: event.target.value })} /></label>}</fieldset>}
        <fieldset id="node-results" className="creatio-settings-category"><legend>Results and routing</legend><label>Payload<select value={settings.outputMode} onChange={event => updateSettings({ outputMode: event.target.value })}><option value="replace">Replace with result</option><option value="merge-input">Merge result into explicit input</option></select></label>
          {edit.value.operationVersion === 1 && <><label>Action field<input data-testid="ai-primitive-action-path" value={settings.actionPath ?? ''} onChange={event => updateSettings({ actionPath: event.target.value || undefined })} /></label><small>When there are multiple success edges, return an exact action ID in this JSON field.</small></>}
          <JsonConfigField label="Saved variable mappings (source is result)" testId="ai-primitive-outputs" value={settings.outputs ?? {}} onChange={outputs => updateSettings({ outputs })} />{workflow.edges.filter(edge => edge.source === edit.value.id).map(edge => <p key={edge.id}><code>{edge.id}</code> / {edge.name} → {workflow.nodes.find(node => node.id === edge.target)?.label} ({edge.kind ?? 'success'})</p>)}
        </fieldset>
        <details className="creatio-settings-category"><summary>Chat status updates</summary><p>Optional messages shown in chat and linked to this attempt. Leave a phase empty to keep it silent. Model nodes can also opt into agent.report_status.</p>
          {['start', 'success', 'failure'].map(phase => <div key={phase}><label><input type="checkbox" checked={Boolean(settings.statusMessages?.[phase])} onChange={event => updateSettings({ statusMessages: event.target.checked ? { ...settings.statusMessages, [phase]: { value: '' } } : Object.fromEntries(Object.entries(settings.statusMessages ?? {}).filter(([key]) => key !== phase)) })} /> Report on {phase}</label>
            {settings.statusMessages?.[phase] && <BindingField label={phase + ' message'} testId={'ai-status-' + phase} binding={settings.statusMessages[phase]} onChange={binding => updateSettings({ statusMessages: { ...settings.statusMessages, [phase]: binding } })} />}</div>)}
        </details>
        <details><summary>Advanced settings JSON</summary><JsonConfigField label="All execution settings" testId="ai-primitive-settings" value={settings} onChange={settings => {
          if (!settings || typeof settings !== 'object' || Array.isArray(settings) || settings.toolNames !== undefined && !Array.isArray(settings.toolNames) || settings.operations !== undefined && !Array.isArray(settings.operations)) { setError('Settings must be an object; toolNames and operations must be arrays.'); return; }
          updateNode({ settings });
        }} /></details>
        <fieldset className="creatio-settings-category"><legend>Effective request preview</legend><JsonConfigField label="Sample state" testId="ai-primitive-sample" value={sample} onChange={setSample} /><EditorActionButton icon={Play} onClick={() => { try {
          const input = resolvePrimitiveBinding(settings.input, sample), native = edit.value.operationVersion === 2;
          const request = { ...settings, input, workflow, node: edit.value, instructionSkills: (settings.instructionSkillIds ?? []).map(id => nodeSkills.find(skill => skill.id === id)).filter(Boolean), ...(settings.context ? { context: resolvePrimitiveBinding(settings.context, sample) } : {}) };
          setPreview({ input, ...(edit.value.handler === 'llm' ? { messages: native ? nativeModelMessages(request) : [{ role: 'system', content: settings.systemPrompt }, { role: 'user', content: JSON.stringify({ input, ...(settings.actionPath ? { availableActions: primitiveActions(workflow, edit.value.id) } : {}) }) }], tools: [...catalog.tools.filter(tool => settings.toolNames.includes(tool.name)).map(tool => ({ type: 'function', function: { name: tool.name, description: tool.description, parameters: tool.schema } })), ...(native ? [nativeFinishTool(workflow, edit.value, request)].filter(Boolean) : [])], responseSchema: settings.responseSchema } : {}) });
        } catch (error) { setError(error.message); } }}>Preview</EditorActionButton>{preview && <JsonInspector value={preview} />}</fieldset>
      </>}
      {edit.kind === 'edge' && <fieldset className="creatio-settings-category"><legend>Result and exits</legend>{['id', 'name', 'description'].map(field => <label key={field}>{field}<input data-testid={`ai-action-${field}`} value={edit.value[field] ?? ''} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, [field]: event.target.value } }))} /></label>)}{['source', 'target'].map(field => <label key={field}>{field}<select data-testid={`ai-action-${field}`} value={edit.value[field]} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, [field]: event.target.value } }))}>{workflow.nodes.map(node => <option key={node.id} value={node.id}>{node.label}</option>)}</select></label>)}<label>Branch<select data-testid="ai-action-kind" value={edit.value.kind ?? 'success'} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, kind: event.target.value } }))}><option value="success">Model-selected exit / normal action</option><option value="tools">Native requests → Tool</option><option value="result">Tool result / human response → reasoning</option><option value="approval">Exact action approval</option><option value="error">Execution or schema error</option></select></label><label>Completion evidence<select value={edit.value.evidencePolicy ?? 'optional'} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, evidencePolicy: event.target.value } }))}><option value="optional">Optional references</option><option value="required">Require successful recorded observations</option></select></label><JsonConfigField label="Optional result JSON schema" value={edit.value.resultSchema ?? null} onChange={resultSchema => setEdit(current => ({ ...current, value: { ...current.value, resultSchema: resultSchema || undefined } }))} /><p>For native LLM nodes, these saved exit IDs, descriptions and contracts generate finish_step automatically. Tool and recovery connections are mechanical, not model-selectable exits.</p></fieldset>}
      {edit.kind === 'edge' && <fieldset className="creatio-settings-category"><legend>Evidence verification</legend><JsonConfigField label="Evidence checks" testId="ai-action-evidence-checks" value={edit.value.evidenceChecks ?? []} onChange={evidenceChecks => setEdit(current => ({ ...current, value: { ...current.value, evidenceChecks } }))} /><JsonConfigField label="Allowed context evidence paths (empty requires tool observations)" testId="ai-action-context-evidence" value={edit.value.contextEvidencePaths ?? []} onChange={contextEvidencePaths=>setEdit(current=>({...current,value:{...current.value,contextEvidencePaths}}))}/><small>The user question and unverified canvas metadata are not product evidence. Explicit context paths are an author policy; tool-specific checks remain authoritative.</small>
        <label>Offer this model exit<select value={edit.value.availableWhen?.operator ?? ''} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, availableWhen: event.target.value ? { operator: event.target.value, path: current.value.availableWhen?.path ?? 'input.field' } : undefined } }))}><option value="">Always</option><option value="present">When a bound value is present</option><option value="missing">When a bound value is missing</option></select></label>
        {edit.value.availableWhen && <label>Bound path<input value={edit.value.availableWhen.path} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, availableWhen: { ...current.value.availableWhen, path: event.target.value } } }))} /><small>Use an input or context path, such as input.saved.codingInspection.</small></label>}
      </fieldset>}
      {edit.kind === 'edge' && <fieldset className="creatio-settings-category"><legend>Alternative evidence paths</legend><p>Every ordinary check still applies. If you add alternatives, the result must also satisfy every check in at least one path.</p><JsonConfigField label="Evidence alternatives" value={edit.value.evidenceAlternatives ?? []} onChange={evidenceAlternatives => setEdit(current => ({ ...current, value: { ...current.value, evidenceAlternatives: Array.isArray(evidenceAlternatives) && !evidenceAlternatives.length ? undefined : evidenceAlternatives } }))} /></fieldset>}
      {edit.kind === 'node' && edit.value.handler === 'workflow' && <label><input type="checkbox" checked={settings.returnEvidence ?? false} onChange={event => updateSettings({ returnEvidence: event.target.checked })} />Return child observations with its result<small>Output becomes value plus observations. Recorded evidence remains authoritative and is available for parent exit verification.</small></label>}
      {edit.kind === 'resources' && <><p>Skills are editable versioned knowledge, loaded only through skills.list/search/read/reference. Saving changes creates no implicit prompt injection; an execution uses its pinned revision.</p><JsonConfigField label="Skills (id, title, description, version, body, references)" testId="ai-primitive-skills-json" value={edit.value.skills ?? []} onChange={skills => setEdit(current => ({ ...current, value: { ...current.value, skills } }))} /></>}
      {edit.kind === 'settings' && <><label>Name<input value={edit.value.name} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, name: event.target.value } }))} /></label><label>Default profile<select value={edit.value.profileId ?? ''} onChange={event => setEdit(current => ({ ...current, value: { ...current.value, profileId: event.target.value || null } }))}><option value="">Workspace profile</option>{profiles.map(profile => <option key={profile.id} value={profile.id}>{profile.displayName} / {profile.model}</option>)}</select></label><ProfileSettings workspaceId={workspaceId}/></>}
    </ComponentSettingsDialog>}
  </section>;
}
